xml.Script:
        include 'Figures\Scripts\Cube_Standard_Colors.inc';

        W := 0.6;
        N := 6;
        D := W / N;
        WX := D;
        WY := D*2;
        WZ := D;

        S[0] := '   1  ';
        S[1] := '  11  ';
        S[2] := ' 111  ';
        S[3] := '1111  ';
        S[4] := '      ';
        S[5] := '      ';

        function GetType(x1, z1);
        begin
            if (x1 < 0) or (z1 < 0) or (x1 >= N) or (z1 >= N) then
                Result := ' '
            else
                Result := copy(S[N-1-z1], x1 + 1, 1);
        end;

        procedure CalcCubie(No);
        begin
            x := No mod N;
            z := No div N;
            Colors[0] := -1;
            Colors[1] := -1;
            Colors[4] := -1;
            Colors[5] := -1;
            CType := GetType(x,z);
            if CType = '1' then begin
                if GetType(x-1,z) = ' ' then Colors[0] := clRed;
                if GetType(x+1,z) = ' ' then Colors[1] := clOrange;
                if GetType(x,z-1) = ' ' then Colors[4] := clYellow;
                if GetType(x,z+1) = ' ' then Colors[5] := clWhite;
            end;
            if CType <> ' ' then begin 
                DWX := D * (2 * x - N + 1);
                DWZ := D * (2 * z - N + 1);
                CCount := 1;
            end else
                CCount := 0;
        end;
